/**
 * HTTP SERVER spans. Inbound requests extract W3C `traceparent` only.
 */
import { context, propagation, SpanKind, SpanStatusCode, trace, } from "@opentelemetry/api";
import { describeError } from "../describe-error.js";
import { ensureW3cPropagator } from "./propagation.js";
const HTTP_SPAN_HANDLE_KEY = Symbol.for("anysphere.july.otel.httpSpanHandle");
/** End the inbound SERVER span once the Fetch status is known (hosted flush). */
export function endActiveHttpSpan(statusCode, error) {
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- this module stores the span handle on the active context under its own symbol
    const handle = context.active().getValue(HTTP_SPAN_HANDLE_KEY);
    handle?.end(statusCode, error);
}
/**
 * Instrument one inbound Node request: SERVER span, W3C extract, auto-end
 * on response finish/close, run `fn` under the span context.
 */
export function instrumentHttp(runtime, req, res, fn) {
    const handle = startHttpSpan(runtime, req);
    if (handle === undefined) {
        return fn();
    }
    res.once("finish", () => {
        handle.end(res.statusCode);
    });
    res.once("close", () => {
        if (!res.writableFinished) {
            handle.end(res.statusCode || 499);
        }
    });
    return context.with(handle.context.setValue(HTTP_SPAN_HANDLE_KEY, handle), fn);
}
function startHttpSpan(runtime, req) {
    if (runtime.config.traces === false) {
        return undefined;
    }
    ensureW3cPropagator();
    const headers = {};
    for (const [key, value] of Object.entries(req.headers)) {
        if (typeof value === "string") {
            headers[key] = value;
        }
        else if (Array.isArray(value) && value[0] !== undefined) {
            headers[key] = value[0];
        }
    }
    const parent = propagation.extract(context.active(), headers);
    const method = req.method ?? "GET";
    const path = (req.url ?? "/").split("?")[0] ?? "/";
    const started = Date.now();
    const span = runtime.tracer.startSpan("agent_sdk.http", {
        kind: SpanKind.SERVER,
        attributes: {
            "http.request.method": method,
            "url.path": path,
            "network.peer.address": req.socket.remoteAddress ?? "",
        },
    }, parent);
    const ctx = trace.setSpan(parent, span);
    let ended = false;
    return {
        context: ctx,
        end(statusCode, error) {
            if (ended) {
                return;
            }
            ended = true;
            span.setAttribute("http.response.status_code", statusCode);
            if (error !== undefined) {
                span.recordException(error instanceof Error ? error : new Error(describeError(error)));
                span.setStatus({
                    code: SpanStatusCode.ERROR,
                    message: describeError(error),
                });
            }
            else if (statusCode >= 500) {
                span.setStatus({ code: SpanStatusCode.ERROR });
            }
            else {
                span.setStatus({ code: SpanStatusCode.OK });
            }
            span.end();
            runtime.httpDuration?.record(Date.now() - started, {
                "http.request.method": method,
                "http.response.status_code": statusCode,
                "url.path": routeClass(path),
            });
        },
    };
}
function routeClass(path) {
    return path
        .replace(/\/sessions\/[0-9a-f-]{8,}/gi, "/sessions/:id")
        .replace(/\/[0-9a-f]{8,}(?:-[0-9a-f]{4,})+/gi, "/:id");
}
